(async () => {
   const { fadeFinder } = await import('/systems/fantastic-depths/module/fantastic-depths.min.js');

   let tier = null;
   let permitUnusual = true;
   try {
      const choice = await foundry.applications.api.DialogV2.prompt({
         window: { title: 'Magical Weapons and Armor' },
         content: '<p style="margin:0 0 0.5rem;">Select the treasure tier to determine the weapon/armor modifier (+0, +6, or +12).</p><div style="display:flex;align-items:center;gap:1rem;padding:0.25rem 0 0.5rem;"><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="minor" checked style="margin:0;width:auto;flex:none;"> Minor (+0)</label><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="medium" style="margin:0;width:auto;flex:none;"> Medium (+6)</label><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="radio" name="tier" value="major" style="margin:0;width:auto;flex:none;"> Major (+12)</label></div><label style="display:flex;align-items:center;gap:0.3rem;margin:0;cursor:pointer;"><input type="checkbox" name="permitUnusual" checked style="margin:0;width:auto;flex:none;"> Permit Unusual Weapon/Armor (rows 19-20); re-roll if unchecked</label>',
         ok: {
            label: 'Roll',
            callback: (event, button) => ({
               tier: button.form.elements.tier.value,
               permitUnusual: button.form.elements.permitUnusual.checked
            })
         }
      });
      tier = { minor: 0, medium: 6, major: 12 }[choice?.tier] ?? null;
      permitUnusual = choice?.permitUnusual !== false;
   } catch (err) {
      tier = null;
   }
   if (tier === null) return;

   const pack = game.packs.get('fade-white-box-fmag.items');
   let allItems = null;
   const findItem = async (name) => {
      if (!allItems) allItems = await pack.getDocuments();
      return allItems.find(i => i.name === name);
   };

   const MELEE = ['Axe, Battle', 'Axe, Hand', 'Club', 'Dagger', 'Flail', 'Mace', 'Morning Star', 'Polearm', 'Spear', 'Staff', 'Sword, Long', 'Sword, Short', 'Sword, Two-Handed', 'Warhammer'];
   const ARMOR = ['Leather Armor', 'Chain Mail', 'Plate Mail'];
   const ARMOR_SHIELD = ['Leather Armor', 'Chain Mail', 'Plate Mail', 'Shield'];
   const CURSED_MELEE = ['Axe, Battle', 'Axe, Hand', 'Dagger', 'Mace', 'Spear', 'Staff', 'Sword, Long', 'Sword, Short', 'Sword, Two-Handed', 'Warhammer'];
   const pick = arr => arr[Math.floor(Math.random() * arr.length)];

   const ROWS = {
      1: { label: 'Cursed Armor or Shield', type: 'cursedArmorShield' },
      2: { label: '+1 Missile Weapon(s)', type: 'missile', bonus: 1 },
      3: { label: '+1 Shield', type: 'shield', bonus: 1 },
      4: { label: '+1 Melee Weapon', type: 'melee', bonus: 1 },
      5: { label: '+1 Melee Weapon', type: 'melee', bonus: 1 },
      6: { label: '+1 Melee Weapon', type: 'melee', bonus: 1 },
      7: { label: '+1 Armor', type: 'armor', bonus: 1 },
      8: { label: '+1 Armor', type: 'armor', bonus: 1 },
      9: { label: 'Cursed Weapon', type: 'cursedWeapon' },
      10: { label: '+2 Missile Weapon(s)', type: 'missile', bonus: 2 },
      11: { label: '+2 Shield', type: 'shield', bonus: 2 },
      12: { label: '+2 Melee Weapon', type: 'melee', bonus: 2 },
      13: { label: '+2 Armor', type: 'armor', bonus: 2 },
      14: { label: '+1 Melee Weapon with Minor Ability', type: 'meleeMinor', bonus: 1 },
      15: { label: '+3 Missile Weapon(s)', type: 'missile', bonus: 3 },
      16: { label: '+3 Melee Weapon', type: 'melee', bonus: 3 },
      17: { label: '+3 Shield', type: 'shield', bonus: 3 },
      18: { label: '+3 Armor', type: 'armor', bonus: 3 },
      19: { label: 'Unusual Weapon (optional) or Re-roll', type: 'unusualWeapon' },
      20: { label: 'Unusual Armor (optional) or Re-roll', type: 'unusualArmor' }
   };

   let base, total, row;
   do {
      base = await new Roll('1d8').roll();
      total = base.total + tier;
      row = ROWS[total];
   } while (!permitUnusual && (total === 19 || total === 20));

   const lines = [
      '<div class="text-size16"><strong>Magical Weapons and Armor</strong></div>',
      `<p>Roll: ${base.result} + ${tier} = <strong>${total}</strong> &mdash; ${row.label}</p><hr/>`
   ];
   const itemLink = item => `@UUID[${item.uuid}]{${item.name}}`;

   switch (row.type) {
      case 'shield': {
         const item = await findItem(`+${row.bonus} Shield`);
         lines.push(item ? `<p><strong>+${row.bonus} Shield</strong>: ${itemLink(item)}</p>` : `<p><strong>+${row.bonus} Shield</strong> (no item found)</p>`);
         break;
      }
      case 'armor': {
         const type = pick(ARMOR);
         const item = await findItem(`+${row.bonus} ${type}`);
         lines.push(item ? `<p><strong>+${row.bonus} ${type}</strong>: ${itemLink(item)}</p>` : `<p><strong>+${row.bonus} ${type}</strong> (no item found)</p>`);
         break;
      }
      case 'melee': {
         const type = pick(MELEE);
         const item = await findItem(`+${row.bonus} ${type}`);
         lines.push(item ? `<p><strong>+${row.bonus} ${type}</strong>: ${itemLink(item)}</p>` : `<p><strong>+${row.bonus} ${type}</strong> (no item found)</p>`);
         break;
      }
      case 'meleeMinor': {
         const type = pick(MELEE);
         const abilityRoll = await new Roll('1d6').roll();
         const minor = abilityRoll.total <= 4
            ? { name: 'Additional damage (+1)', item: `+${row.bonus} ${type}` }
            : { name: abilityRoll.total === 5 ? 'Sheds light, 15 ft. radius' : 'Sheds light, 30 ft. radius', item: `+${row.bonus} ${type} of Light` };
         const item = await findItem(minor.item);
         lines.push(item ? `<p><strong>${minor.item}</strong> (d6 ${abilityRoll.total}: ${minor.name}): ${itemLink(item)}</p>` : `<p><strong>${minor.item}</strong> (d6 ${abilityRoll.total}: ${minor.name})</p>`);
         break;
      }
      case 'missile': {
         const specRoll = await new Roll('1d20').roll();
         const t = specRoll.total;
         const spec = t <= 8 ? { qty: '2d6', label: 'Arrows', item: `+${row.bonus} Arrows` }
            : t <= 10 ? { qty: '1d10', label: 'Stones', item: `+${row.bonus} Stones` }
            : t === 11 ? { qty: null, label: 'Spear', item: `+${row.bonus} Spear` }
            : t <= 15 ? { qty: '2d4', label: 'Darts', item: null }
            : { qty: '2d6', label: 'Bolts, crossbow', item: `+${row.bonus} Bolts` };
         const count = spec.qty ? (await new Roll(spec.qty).roll()).total : 1;
         const item = spec.item ? await findItem(spec.item) : null;
         const name = `${count} +${row.bonus} ${spec.label}`;
         lines.push(item ? `<p><strong>${name}</strong>: ${itemLink(item)}</p>` : `<p><strong>${name}</strong></p>`);
         break;
      }
      case 'cursedArmorShield': {
         const c55 = await new Roll('1d6').roll();
         const type = pick(ARMOR_SHIELD);
         if (c55.total <= 5) {
            const minus = c55.total <= 3 ? 1 : (c55.total === 4 ? 2 : 3);
            const item = await findItem(`-${minus} ${type}`);
            lines.push(item ? `<p><strong>Cursed -${minus} ${type}</strong> (d6 ${c55.total}): ${itemLink(item)}</p>` : `<p><strong>Cursed -${minus} ${type}</strong> (d6 ${c55.total})</p>`);
         } else {
            const item = await findItem(`Cursed ${type} (Attracts Missiles)`);
            lines.push(item ? `<p><strong>Cursed ${type} (Attracts Missiles)</strong> (d6 ${c55.total}): ${itemLink(item)}</p>` : `<p><strong>Cursed ${type} (Attracts Missiles)</strong> (d6 ${c55.total})</p>`);
         }
         break;
      }
      case 'cursedWeapon': {
         const c55 = await new Roll('1d6').roll();
         if (c55.total <= 5) {
            const minus = c55.total <= 3 ? 1 : (c55.total === 4 ? 2 : 3);
            const type = pick(CURSED_MELEE);
            const item = await findItem(`-${minus} ${type}`);
            lines.push(item ? `<p><strong>Cursed -${minus} ${type}</strong> (d6 ${c55.total}): ${itemLink(item)}</p>` : `<p><strong>Cursed -${minus} ${type}</strong> (d6 ${c55.total})</p>`);
         } else {
            lines.push(`<p><strong>Cursed Weapon (Attracts Missiles)</strong> (d6 ${c55.total}): attracts missile fire, even that fired at others nearby.</p>`);
         }
         break;
      }
      case 'unusualWeapon': {
         const table = await fadeFinder.getRollTable('Magic Unusual Weapons');
         if (!table) { ui.notifications.error('Magic Unusual Weapons roll table not found.'); return; }
         const draw = await table.draw({ displayChat: false });
         const html = (draw.results[0]?.text ?? '').replace(/^<p>(.*)<\/p>\s*$/s, '$1');
         lines.push(`<p><strong>Unusual Weapon</strong>: ${html}</p>`);
         break;
      }
      case 'unusualArmor': {
         const table = await fadeFinder.getRollTable('Unusual Armor');
         if (!table) { ui.notifications.error('Unusual Armor roll table not found.'); return; }
         const draw = await table.draw({ displayChat: false });
         const html = (draw.results[0]?.text ?? '').replace(/^<p>(.*)<\/p>\s*$/s, '$1');
         lines.push(`<p><strong>Unusual Armor</strong>: ${html}</p>`);
         break;
      }
   }

   await ChatMessage.create({ content: lines.join(''), speaker: ChatMessage.getSpeaker() });
})();
